import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.q07Y7wJQ.js";var i=JSON.parse(`{"title":"Fetch Multiple Data (Vertical)","description":"","frontmatter":{"prev":{"text":"Fetch Header-Value Data","link":"/documentation/field-types/scraper-data/fetch-header-value-data"},"next":{"text":"Fetch Table Data (Horizontal)","link":"/documentation/field-types/scraper-data/fetch-table-data-horizontal"}},"headers":[],"relativePath":"documentation/field-types/scraper-data/fetch-multiple-data-vertical.md","filePath":"documentation/field-types/scraper-data/fetch-multiple-data-vertical.md","lastUpdated":1788551488000}`),a={name:`documentation/field-types/scraper-data/fetch-multiple-data-vertical.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="fetch-multiple-data-vertical" tabindex="-1">Fetch Multiple Data (Vertical) <a class="header-anchor" href="#fetch-multiple-data-vertical" aria-label="Permalink to “Fetch Multiple Data (Vertical)”">​</a></h1><p>Harvest repeating item collections (such as product grids, catalog cards, or search results) from web pages into vertical <code>.xlsx</code> row datasets.</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to “Overview”">​</a></h2><p>The <strong>Fetch Multiple Data (Vertical)</strong> field type extracts repeating occurrences of web elements across a page. For every matching node found, the extension captures the chosen property (text, attribute, href, or image URL) and appends it as a distinct row under <a href="/documentation/site/site-scraper-data.html">Scraper Data</a>.</p><hr><h2 id="configuration-options" tabindex="-1">Configuration Options <a class="header-anchor" href="#configuration-options" aria-label="Permalink to “Configuration Options”">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Description</th><th>Required</th></tr></thead><tbody><tr><td><strong>Selector Type</strong></td><td>Syntax type (<code>CSS</code> or <code>XPath</code>).</td><td>Yes</td></tr><tr><td><strong>Selector Query</strong></td><td>Target query matching all repeating items on the page.</td><td>Yes</td></tr><tr><td><strong>Which Element Option Scraping</strong></td><td>The specific property to extract from each matched node.</td><td>Yes</td></tr><tr><td><strong>Element Attribute Name</strong></td><td>Attribute to extract when <code>Element Attribute</code> is selected (e.g., <code>data-id</code>).</td><td>Conditional</td></tr><tr><td><strong>Wait until element is found in the page</strong></td><td>Pauses execution until at least one matching node appears.</td><td>No</td></tr></tbody></table><hr><h2 id="scraping-options" tabindex="-1">Scraping Property Options <a class="header-anchor" href="#scraping-options" aria-label="Permalink to “Scraping Property Options”">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Extraction Target</th><th>Typical Use Case</th></tr></thead><tbody><tr><td><strong>Element Text</strong></td><td>Visible text (<code>innerText</code> / <code>textContent</code>).</td><td>Titles, prices, descriptions, ratings.</td></tr><tr><td><strong>Element Value</strong></td><td>Input field <code>value</code> attribute.</td><td>Form inputs, hidden tokens, counters.</td></tr><tr><td><strong>Element HTML</strong></td><td>Inner markup (<code>innerHTML</code>).</td><td>Formatted HTML blocks or styled badges.</td></tr><tr><td><strong>Element Attribute</strong></td><td>Value of any arbitrary HTML attribute.</td><td>IDs (<code>data-sku</code>), stock status (<code>data-stock</code>).</td></tr><tr><td><strong>Element Text/Value</strong></td><td>Auto-detects text or input value.</td><td>Mixed lists of static text and inputs.</td></tr><tr><td><strong>Element Link</strong></td><td>Hyperlink URL (<code>href</code> attribute).</td><td>Product links, article URLs.</td></tr><tr><td><strong>Element Image Link</strong></td><td>Image source URL (<code>src</code> attribute).</td><td>Thumbnails, gallery images.</td></tr></tbody></table><hr><h2 id="workflow-details" tabindex="-1">Extraction Flow &amp; Multi-Column Workflows <a class="header-anchor" href="#workflow-details" aria-label="Permalink to “Extraction Flow &amp; Multi-Column Workflows”">​</a></h2><p>Each <strong>Fetch Multiple Data (Vertical)</strong> field generates one dedicated column of vertical rows. To extract multi-dimensional datasets (e.g., Product Title, Price, and Product Link together into one Excel row per item):</p><ol><li><strong>Field 1 (Product Name)</strong>: <ul><li>Selector: <code>.product-card .product-title</code></li><li>Property: <code>Element Text</code></li></ul></li><li><strong>Field 2 (Product Price)</strong>: <ul><li>Selector: <code>.product-card .price-tag</code></li><li>Property: <code>Element Text</code></li></ul></li><li><strong>Field 3 (Product URL)</strong>: <ul><li>Selector: <code>.product-card a.product-link</code></li><li>Property: <code>Element Link</code></li></ul></li></ol><p>During execution, the extension aligns row indexes across fields to assemble a clean tabular <code>.xlsx</code> spreadsheet.</p><hr><h2 id="examples" tabindex="-1">Practical Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Practical Examples”">​</a></h2><h3 id="example-1-extracting-search-result-titles" tabindex="-1">Example 1: Extracting Search Result Titles <a class="header-anchor" href="#example-1-extracting-search-result-titles" aria-label="Permalink to “Example 1: Extracting Search Result Titles”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Selector Type: CSS</span></span>
<span class="line"><span>Selector Query: div.search-result h2.title</span></span>
<span class="line"><span>Which Element Option Scraping: Element Text</span></span>
<span class="line"><span>Wait until element is found: Enabled</span></span></code></pre></div><h3 id="example-2-extracting-product-image-urls" tabindex="-1">Example 2: Extracting Product Image URLs <a class="header-anchor" href="#example-2-extracting-product-image-urls" aria-label="Permalink to “Example 2: Extracting Product Image URLs”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Selector Type: CSS</span></span>
<span class="line"><span>Selector Query: .product-grid img.thumbnail</span></span>
<span class="line"><span>Which Element Option Scraping: Element Image Link</span></span></code></pre></div><h3 id="example-3-extracting-custom-data-attribute" tabindex="-1">Example 3: Extracting Custom Data Attribute <a class="header-anchor" href="#example-3-extracting-custom-data-attribute" aria-label="Permalink to “Example 3: Extracting Custom Data Attribute”">​</a></h3><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Selector Type: CSS</span></span>
<span class="line"><span>Selector Query: tr.order-row</span></span>
<span class="line"><span>Which Element Option Scraping: Element Attribute</span></span>
<span class="line"><span>Element Attribute Name: data-order-id</span></span></code></pre></div><hr><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to “Best Practices”">​</a></h2><ul><li><strong>Test Selectors with <code>querySelectorAll</code></strong>: Verify in DevTools console (<code>document.querySelectorAll(&#39;.item&#39;).length</code>) that the selector captures the intended count.</li><li><strong>Ensure Count Alignment</strong>: When scraping multiple columns for the same entities, verify all selectors return identical element lengths.</li><li><strong>Handle Infinite Scroll</strong>: If the target page lazy-loads items upon scrolling, combine with page scroll actions or <a href="/documentation/field-types/loop.html">Loop</a> before triggering the scraper.</li></ul><hr><h2 id="related" tabindex="-1">Related Documentation <a class="header-anchor" href="#related" aria-label="Permalink to “Related Documentation”">​</a></h2><ul><li><img src="/svg/excel.svg" class="doc-icon"> <a href="/documentation/site/site-scraper-data.html">Scraper Data Management Dashboard</a></li><li><img src="/svg/click.svg" class="doc-icon"> <a href="/documentation/field-types/scraper-data/fetch-table-data-horizontal.html">Fetch Table Data (Horizontal)</a></li><li><img src="/svg/database.svg" class="doc-icon"> <a href="/documentation/field-types/scraper-data/fetch-table-data-vertical.html">Fetch Table Data (Vertical)</a></li><li><img src="/svg/form.svg" class="doc-icon"> <a href="/documentation/field-types/scraper-data/fetch-header-value-data.html">Fetch Header-Value Data</a></li><li><img src="/svg/template.svg" class="doc-icon"> <a href="/documentation/field-types/loop.html">Loop Field Type</a></li></ul>`,30)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};